// Runs the shared cross-language vectors (control-plane/testdata/deployment-pass-vectors.json,
// generated by the Go reference) through the C++/CNG verifier in deployment_pass.h.
//
// scripts/test-setup.ps1 converts the JSON into a tab-separated stream so this test needs no
// general JSON reader (the files hold no tabs or newlines inside values):
//   R <root_pubkey>
//   V <name> <kind> <pubkey or -> <envelope_b64> <now> <expect>
//   F <field> <value>          (expected fields of the preceding ok vector)
#include "deployment_pass.h"

#include <cstdio>
#include <fstream>
#include <map>
#include <sstream>

namespace {

std::vector<std::string> SplitTabs(const std::string& line) {
    std::vector<std::string> out;
    std::string cur;
    for (char c : line) {
        if (c == 0x09) { out.push_back(cur); cur.clear(); }
        else if (c != 0x0D) cur.push_back(c);
    }
    out.push_back(cur);
    return out;
}

struct Vec {
    std::string name, kind, pubkey, env_b64, now, expect;
    std::map<std::string, std::string> fields;
};

std::map<std::string, std::string> PassFields(const dp::DeploymentPass& p) {
    return {{"pass_id", p.pass_id}, {"issued_to", p.issued_to}, {"origin", p.origin}, {"host_port", p.HostPort()},
            {"control_plane_url", p.ControlPlaneUrl()}, {"signaling_url", p.SignalingUrl()},
            {"grant_issuer_pubkey", p.grant_issuer_pubkey}, {"for_setup", p.for_setup ? "true" : "false"},
            {"for_support", p.for_support ? "true" : "false"}, {"min_agent_version", p.min_agent_version},
            {"issued_at", dp::FormatTime(p.issued_at)}, {"expires_at", dp::FormatTime(p.expires_at)}};
}

std::map<std::string, std::string> ReleaseFields(const dp::AgentRelease& r) {
    return {{"msi_sha256", r.msi_sha256}, {"msi_size", std::to_string(r.msi_size)}, {"product_version", r.product_version},
            {"product_code", r.product_code}, {"upgrade_code", r.upgrade_code}, {"arch", r.arch},
            {"issued_at", dp::FormatTime(r.issued_at)}, {"expires_at", dp::FormatTime(r.expires_at)}};
}

}  // namespace

int main(int argc, char** argv) {
    if (argc != 2) {
        std::fprintf(stderr, "usage: test_pass_vectors <vectors.tsv>\n");
        return 2;
    }
    std::ifstream in(argv[1], std::ios::binary);
    if (!in) {
        std::fprintf(stderr, "cannot open %s\n", argv[1]);
        return 2;
    }
    std::string root, line;
    std::vector<Vec> vecs;
    while (std::getline(in, line)) {
        const auto cols = SplitTabs(line);
        if (cols[0] == "R" && cols.size() == 2) root = cols[1];
        else if (cols[0] == "V" && cols.size() == 7) vecs.push_back(Vec{cols[1], cols[2], cols[3], cols[4], cols[5], cols[6], {}});
        else if (cols[0] == "F" && cols.size() == 3 && !vecs.empty()) vecs.back().fields[cols[1]] = cols[2];
        else if (!line.empty()) { std::fprintf(stderr, "bad line: %s\n", line.c_str()); return 2; }
    }
    if (root.empty() || vecs.size() < 138) {
        std::fprintf(stderr, "only %zu vectors (or no root key): not the shared contract\n", vecs.size());
        return 2;
    }
    int failures = 0;
    std::map<std::string, int> seen;
    for (const auto& v : vecs) {
        seen[v.expect]++;
        std::string env;
        long long now = 0;
        if (!dp::Base64Canonical(v.env_b64, env) || !dp::ParseTime(v.now, now)) {
            std::fprintf(stderr, "%s: unreadable vector\n", v.name.c_str());
            return 2;
        }
        dp::RootKey key;
        dp::Result r = key.Load(v.pubkey == "-" ? root : v.pubkey);
        std::map<std::string, std::string> fields;
        if (r.ok()) {
            if (v.kind == "pass") {
                dp::DeploymentPass p;
                r = dp::VerifyPass(key, env, now, p);
                if (r.ok()) fields = PassFields(p);
            } else if (v.kind == "release") {
                dp::AgentRelease rel;
                r = dp::VerifyRelease(key, env, now, rel);
                if (r.ok()) fields = ReleaseFields(rel);
            } else {
                std::fprintf(stderr, "%s: unknown kind %s\n", v.name.c_str(), v.kind.c_str());
                return 2;
            }
        }
        const std::string got = dp::KindName(r.kind);
        if (got != v.expect) {
            std::printf("FAIL %s: got %s (%s), want %s\n", v.name.c_str(), got.c_str(), r.reason.c_str(), v.expect.c_str());
            failures++;
        } else if (r.ok()) {
            if (v.fields.empty()) {
                std::printf("FAIL %s: an ok vector must list its fields\n", v.name.c_str());
                failures++;
            } else if (fields != v.fields) {
                std::printf("FAIL %s: fields differ\n", v.name.c_str());
                for (const auto& kv : v.fields) {
                    const auto it = fields.find(kv.first);
                    if (it == fields.end() || it->second != kv.second)
                        std::printf("  %s: got [%s] want [%s]\n", kv.first.c_str(), it == fields.end() ? "<none>" : it->second.c_str(), kv.second.c_str());
                }
                failures++;
            }
        }
    }
    for (const char* k : {"ok", "key", "envelope", "signature", "body", "validity"}) {
        if (seen[k] == 0) {
            std::printf("FAIL no vector expects %s\n", k);
            failures++;
        }
    }
    std::printf("%zu vectors, %d failure(s)\n", vecs.size(), failures);
    return failures == 0 ? 0 : 1;
}
